@@ -30,6 +30,75 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_DESCUENTO = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006 T-01: descuento global del 10 %", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006 T-02: el descuento se redondea al centavo (medio centavo hacia arriba)", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: 5 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 553,
+    totalCentavos: 10497,
+    ivaCentavos: 1365,
+    netoCentavos: 9132,
+  });
+});
+
+test("RF-006 T-03: sin el parámetro el resultado es el de siempre (3 campos)", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, {}), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: undefined }), esperado);
+});
+
+test("RF-006 T-04: descuento 0 explícito", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: 0 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 0,
+    totalCentavos: 11050,
+    ivaCentavos: 1437,
+    netoCentavos: 9613,
+  });
+});
+
+test("RF-006 T-05: descuento total (100 %)", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: 100 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 11050,
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("RF-006 T-06: descuento fuera de 0–100 o no entero → RangeError", () => {
+  for (const invalido of [-1, 101, 10.5, "10", null, NaN]) {
+    assert.throws(() => calcularFactura(LINEAS_DESCUENTO, { descuentoGlobal: invalido }), RangeError, String(invalido));
+  }
+});
+
+test("RF-006 T-07: emitirFactura no cambia", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_DESCUENTO });
+  assert.equal(f.estado, "emitida");
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.totalCentavos, 11050);
+  assert.equal(f.ivaCentavos, 1437);
+  assert.equal(f.netoCentavos, 9613);
+  assert.ok(!("subtotalCentavos" in f));
+  assert.ok(!("descuentoGlobalCentavos" in f));
+});
